UPDATE public.design_imagens_prompts
SET prompt_base = E'Flat vector editorial illustration in the style of a classic "OAB na Risca" law-blog cover.\n\nCUTOUT / "VAZADO" LOOK — NON-NEGOTIABLE:\n- The subject must feel CUT OUT against a pure solid black background, as if placed directly on the dark app UI.\n- NO card, NO frame, NO border, NO rounded panel, NO parchment, NO letterbox, NO vignette, NO gradient.\n- Background is 100% pure #000000, edge-to-edge, so the illustration blends seamlessly with the dark app.\n\nASPECT & FRAMING — NON-NEGOTIABLE:\n- HORIZONTAL / LANDSCAPE aspect ratio 16:9.\n- Main figure and symbolic objects FILL THE FRAME edge-to-edge (top and bottom), with at most a 3% black margin.\n- Figure ~60-65% of horizontal width, standing tall top to bottom; symbolic props stacked to the right, also reaching top-to-bottom.\n\nFIGURE:\n- ONE central historical/classical figure connected to the subject (philosopher, jurist, thinker). Waist-up or three-quarter body, calm expression, occupying LEFT-CENTER.\n- Crisp, well-defined silhouette clearly readable against pure black.\n- Holds a leather-bound book with visible spine.\n- To the RIGHT, a rich stack of symbolic law/philosophy objects reaching top-to-bottom: classical column, scales of justice, quill and inkwell, candle, laurel wreath, stack of old leather-bound books with titles on spines.\n\nSTYLE:\n- Flat vector look. Bold clean ink outlines. Subtle cross-hatching only for shadow depth.\n- Sharp, high-contrast, HIGHLY LEGIBLE at thumbnail size.\n- NO painterly rendering, NO photorealism, NO chiaroscuro glow, NO 3D shading, NO watercolor, NO sculpture/bust look.\n- Palette LIMITED to: cream / tan / warm sepia / muted olive / burgundy / soft gold — ONLY on the figure and objects, NEVER as background.\n- ZERO tolerance for white, cream, tan, beige, ivory, parchment, off-white or ANY light tone at the outer 8% frame border.\n- NO neon, NO blue, NO purple, NO green as background.\n\nCONSTRAINTS:\n- NO text, NO title, NO caption, NO logo, NO watermark, NO signatures.',
    updated_at = now()
WHERE slug = 'filosofia-bustos-classicos';

UPDATE public.design_imagens_prompts
SET prompt_base = E'Flat vector illustration, editorial style. Simple stylized characters with soft features and clean geometric shapes.\n\nCUTOUT / "VAZADO" LOOK — NON-NEGOTIABLE:\n- The scene must feel CUT OUT against a pure solid black background (#000000), edge-to-edge, so it blends seamlessly with the dark app UI.\n- NO card, NO frame, NO border, NO rounded panel, NO letterbox, NO vignette, NO light background band.\n- Characters, props and scenery are rendered as a crisp, high-contrast illustration ON TOP of the black background — never inside a colored rectangle.\n\nASPECT & FRAMING:\n- Horizontal 16:9 landscape.\n- Subject fills the frame edge-to-edge (top and bottom), max 3% black margin.\n- Legal/judicial setting (courtroom, law office, library, classical building, university) simplified so the silhouette is highly legible at thumbnail size.\n\nSCENE:\n- Central subject with symbolic legal props: golden balance scale, thick leather law books, gavel, arched window with warm light, wooden panels, columns.\n- Window light casts angular geometric BLOCK shadows (very characteristic of the style).\n\nSTYLE:\n- Flat vector look. Solid color fills. No gradients, no photorealism, no painterly rendering.\n- Shadows rendered as flat geometric blocks (not soft/blurred).\n- Palette contained to 4-6 harmonious colors ON THE SUBJECT ONLY (VARIES per subject: see the paleta hint below). Background always pure black.\n- Characters with round soft faces, simple hair shapes, slightly stylized proportions.\n\nCONSTRAINTS:\n- NO text, NO title, NO caption, NO logo, NO watermark, NO signatures.\n- Background is ALWAYS pure #000000, never cream, tan, beige, teal, purple or any tinted panel.',
    updated_at = now()
WHERE slug = 'flat-vetorial-juridico';